INSERT INTO bre_rules (tenant_id, code, name, category, version, priority, conditions, action, status, created_by) VALUES (1, 'BRE-CREDIT-01', 'Minimum Credit Score', 'credit_policy', 1, 10, '{"operator":"and","children":[{"operator":"gte","field":"credit.score","value":650}]}', '{"eligible":true,"riskGrade":"high","reason":"Credit score below 650"}', 'active', 1) RETURNING id;
INSERT INTO bre_rules (tenant_id, code, name, category, version, priority, conditions, action, status, created_by) VALUES (1, 'BRE-FOIR-01', 'FOIR within 55%', 'credit_policy', 1, 20, '{"operator":"lte","field":"capacity.foir","value":55}', '{"eligible":true,"riskGrade":"high","reason":"FOIR exceeds 55%"}', 'active', 1) RETURNING id;
INSERT INTO bre_rules (tenant_id, code, name, category, version, priority, conditions, action, status, created_by) VALUES (1, 'BRE-AGE-01', 'Borrower age 21–65', 'credit_policy', 1, 30, '{"operator":"between","field":"customer.age","min":21,"max":65}', '{"eligible":true,"reason":"Age outside policy band"}', 'active', 1) RETURNING id;
INSERT INTO bre_rules (tenant_id, code, name, category, version, priority, conditions, action, status, created_by) VALUES (1, 'BRE-INCOME-01', 'Minimum income ₹20,000', 'credit_policy', 1, 40, '{"operator":"gte","field":"customer.monthly_income","value":20000}', '{"eligible":true,"reason":"Income below ₹20,000"}', 'active', 1) RETURNING id;
INSERT INTO bre_rules (tenant_id, code, name, category, version, priority, conditions, action, status, created_by) VALUES (1, 'BRE-DPD-01', 'No DPD above 30 in bureau', 'credit_policy', 1, 50, '{"operator":"lte","field":"credit.dpd_max","value":30}', '{"eligible":true,"riskGrade":"high","reason":"Bureau DPD above 30 days"}', 'active', 1) RETURNING id;
INSERT INTO bre_rules (tenant_id, code, name, category, version, priority, conditions, action, status, created_by) VALUES (1, 'BRE-EXPOSURE-01', 'Existing exposure cap', 'credit_policy', 1, 60, '{"operator":"lte","field":"exposure.total","value":2500000}', '{"eligible":true,"reason":"Existing exposure exceeds cap"}', 'active', 1) RETURNING id;
INSERT INTO bre_rules (tenant_id, code, name, category, version, priority, conditions, action, status, created_by) VALUES (1, 'BRE-BANK-01', 'Bank statement hygiene', 'credit_policy', 1, 70, '{"operator":"lte","field":"bank.bounce_count","value":2}', '{"eligible":true,"reason":"Excessive cheque bounces"}', 'active', 1) RETURNING id;
INSERT INTO bre_rules (tenant_id, code, name, category, version, priority, conditions, action, status, created_by) VALUES (1, 'BRE-UTIL-01', 'Credit utilization below 90%', 'credit_policy', 1, 80, '{"operator":"lte","field":"credit.utilization","value":90}', '{"eligible":true,"reason":"High credit utilization"}', 'active', 1) RETURNING id;
INSERT INTO bre_rules (tenant_id, code, name, category, version, priority, conditions, action, status, created_by) VALUES (1, 'REG-KFS-01', 'KFS required before acceptance', 'regulatory', 1, 5, '{"operator":"eq","field":"application.stage","value":"kfs"}', '{"eligible":true,"reason":"KFS must be generated and disclosed"}', 'active', 1) RETURNING id;
INSERT INTO bre_rules (tenant_id, code, name, category, version, priority, conditions, action, status, created_by) VALUES (1, 'BRE-POLICY-SIM', 'Proposed FOIR 50% (draft)', 'credit_policy', 1, 15, '{"operator":"lte","field":"capacity.foir","value":50}', '{"eligible":true,"reason":"Draft rule for policy simulation"}', 'draft', 1) RETURNING id;
