INSERT INTO compliance_rules (tenant_id, rule_id, name, source, effective_from, version, status, config) VALUES (1, 'DL-01', 'Key Fact Statement', 'RBI Digital Lending Guidelines', (CURRENT_DATE + INTERVAL '-90 days'), 1, 'active', '{"description":"KFS must disclose APR, fees and amortisation schedule before sanction acceptance"}') RETURNING id;
INSERT INTO compliance_rules (tenant_id, rule_id, name, source, effective_from, version, status, config) VALUES (1, 'DL-02', 'APR Disclosure', 'RBI Digital Lending Guidelines', (CURRENT_DATE + INTERVAL '-90 days'), 1, 'active', '{"description":"APR including all fees must be communicated to the borrower"}') RETURNING id;
INSERT INTO compliance_rules (tenant_id, rule_id, name, source, effective_from, version, status, config) VALUES (1, 'DL-03', 'Consent Management', 'RBI Digital Lending Guidelines', (CURRENT_DATE + INTERVAL '-90 days'), 1, 'active', '{"description":"Explicit, informed consent required before data collection or credit bureau fetch"}') RETURNING id;
INSERT INTO compliance_rules (tenant_id, rule_id, name, source, effective_from, version, status, config) VALUES (1, 'DL-04', 'Data Minimization', 'RBI Digital Lending Guidelines', (CURRENT_DATE + INTERVAL '-90 days'), 1, 'active', '{"description":"Only purpose-limited customer data may be collected"}') RETURNING id;
INSERT INTO compliance_rules (tenant_id, rule_id, name, source, effective_from, version, status, config) VALUES (1, 'DL-05', 'Recovery Conduct', 'RBI Fair Practices Code', (CURRENT_DATE + INTERVAL '-90 days'), 1, 'active', '{"description":"Recovery agents must follow fair conduct and disclosure norms"}') RETURNING id;
INSERT INTO compliance_rules (tenant_id, rule_id, name, source, effective_from, version, status, config) VALUES (1, 'KYC-01', 'Customer Due Diligence', 'RBI KYC Master Directions', (CURRENT_DATE + INTERVAL '-90 days'), 1, 'active', '{"description":"CDD for all customers; EDD for high-risk classifications"}') RETURNING id;
INSERT INTO compliance_rules (tenant_id, rule_id, name, source, effective_from, version, status, config) VALUES (1, 'KYC-02', 'Re-KYC Cycle', 'RBI KYC Master Directions', (CURRENT_DATE + INTERVAL '-90 days'), 1, 'active', '{"description":"Periodic re-KYC per customer risk classification"}') RETURNING id;
INSERT INTO compliance_rules (tenant_id, rule_id, name, source, effective_from, version, status, config) VALUES (1, 'AML-01', 'Sanctions Screening', 'AML/CFT Framework', (CURRENT_DATE + INTERVAL '-90 days'), 1, 'active', '{"description":"Sanctions and PEP screening on customer onboarding"}') RETURNING id;
INSERT INTO compliance_rules (tenant_id, rule_id, name, source, effective_from, version, status, config) VALUES (1, 'PRIV-01', 'Data Residency', 'Data Storage Guidelines', (CURRENT_DATE + INTERVAL '-90 days'), 1, 'active', '{"description":"India-region storage for applicable digital lending data"}') RETURNING id;
INSERT INTO compliance_rules (tenant_id, rule_id, name, source, effective_from, version, status, config) VALUES (1, 'GRV-01', 'Grievance Redressal', 'RBI Integrated Ombudsman Scheme', (CURRENT_DATE + INTERVAL '-90 days'), 1, 'active', '{"description":"Complaints must be acknowledged and resolved within SLA"}') RETURNING id;
