INSERT INTO gn_inbox_messages (tenant_id, direction, channel, from_contact, to_contact, subject, body, related_type, related_id, status, created_by, created_at) VALUES (1, 'in', 'whatsapp', '9977983349', NULL, 'Top-up eligibility', 'I want to check if I''m eligible for a top-up on my existing loan.', 'lead', NULL, 'read', 1, (CURRENT_TIMESTAMP + CAST('-6 days' AS INTERVAL))) RETURNING id;
INSERT INTO gn_inbox_messages (tenant_id, direction, channel, from_contact, to_contact, subject, body, related_type, related_id, status, created_by, created_at) VALUES (1, 'out', 'whatsapp', NULL, '9667097494', 'Welcome to Growth Nations', 'Hi! Welcome to Growth Nations Finance 🎉 Our relationship manager will call you shortly.', 'lead', NULL, 'sent', 1, (CURRENT_TIMESTAMP + CAST('-0 days' AS INTERVAL))) RETURNING id;
INSERT INTO gn_inbox_messages (tenant_id, direction, channel, from_contact, to_contact, subject, body, related_type, related_id, status, created_by, created_at) VALUES (1, 'in', 'call', '9768157046', NULL, 'IVR collections', 'Caller pressed 1 (Payment Assistance) → routed to Collections.', 'application', NULL, 'read', 1, (CURRENT_TIMESTAMP + CAST('-8 days' AS INTERVAL))) RETURNING id;
INSERT INTO gn_inbox_messages (tenant_id, direction, channel, from_contact, to_contact, subject, body, related_type, related_id, status, created_by, created_at) VALUES (1, 'in', 'whatsapp', '9519290466', NULL, 'Agreement status', 'Has my agreement been e-signed by the lender yet1', 'application', NULL, 'unread', 1, (CURRENT_TIMESTAMP + CAST('-2 days' AS INTERVAL))) RETURNING id;
INSERT INTO gn_inbox_messages (tenant_id, direction, channel, from_contact, to_contact, subject, body, related_type, related_id, status, created_by, created_at) VALUES (1, 'out', 'whatsapp', NULL, '9145889251', 'Disbursement Update', 'Your loan of ₹32,00,000 has been disbursed to your account. Thank you for choosing Growth Nations!', 'application', NULL, 'sent', 1, (CURRENT_TIMESTAMP + CAST('-7 days' AS INTERVAL))) RETURNING id;
INSERT INTO gn_docs (tenant_id, title, slug, category, content, updated_by) VALUES (1, 'Welcome to Growth Nations — DSA Quickstart', 'welcome-to-growth-nations-dsa-quickstart', 'Getting Started', 'This guide walks your team through the first 30 days on the platform: activating your DSA code, uploading KYC documents, and submitting your first loan application. Every screen in the platform is database-backed demo data, so you can explore freely without affecting production records.', 1) RETURNING id;
INSERT INTO gn_docs (tenant_id, title, slug, category, content, updated_by) VALUES (1, 'How to Create a Lead', 'how-to-create-a-lead', 'Getting Started', 'Open CRM → Leads → New Lead. Enter the customer''s mobile number, requirement and city. The lead is instantly routed to your telecalling pool per your active workflow. Leads captured via Meta, Google and WhatsApp land here automatically in the demo environment.', 1) RETURNING id;
INSERT INTO gn_docs (tenant_id, title, slug, category, content, updated_by) VALUES (1, 'Creating a Loan Application', 'creating-a-loan-application', 'Loan Origination', 'From a lead, click ''Create Application'' to start the LOS journey: KYC → Documents → Credit → BRE → Underwriting → Approval → Sanction → KFS → Agreement → eSign → Disbursement. Each stage is tracked in the application timeline with SLA timers.', 1) RETURNING id;
INSERT INTO gn_docs (tenant_id, title, slug, category, content, updated_by) VALUES (1, 'Understanding the Lender Match', 'understanding-the-lender-match', 'Loan Origination', 'The matcher evaluates your customer''s profile against every active lender product and returns eligible / maybe / not eligible with reasons. Eligibility depends on amount, tenure, income, vintage, turnover, geography and your configured scheme rules.', 1) RETURNING id;
INSERT INTO gn_docs (tenant_id, title, slug, category, content, updated_by) VALUES (1, 'Reading the Disbursement Dashboard', 'reading-the-disbursement-dashboard', 'Disbursement', 'The disbursement page shows sanctioned-but-undisbursed files, lender-wise breakups and aging. Once a lender confirms disbursal, the status moves to ''Disbursement Confirmed'' and the Growth Nations CRM is updated automatically.', 1) RETURNING id;
INSERT INTO gn_docs (tenant_id, title, slug, category, content, updated_by) VALUES (1, 'Commission & Payout Reconciliation', 'commission-payout-reconciliation', 'Commissions', 'Every disbursed loan earns commission at your configured payout rate. Payouts are batched monthly, reconciled against bank statements, and each transaction is audit-logged. The Wallet shows your earned, pending and received balance.', 1) RETURNING id;
INSERT INTO gn_docs (tenant_id, title, slug, category, content, updated_by) VALUES (1, 'KFS & APR Disclosure', 'kfs-apr-disclosure', 'Compliance', 'Every loan must have a Key Fact Statement generated before acceptance, with the APR calculated and all charges validated. If required information is missing, the platform shows a Compliance Blocker — no hidden charges are ever allowed.', 1) RETURNING id;
INSERT INTO gn_docs (tenant_id, title, slug, category, content, updated_by) VALUES (1, 'Raising a Support Ticket', 'raising-a-support-ticket', 'Support', 'Use Help & FAQ → New Ticket to raise a support request. Tickets are triaged by priority and visible in the Help & FAQ dashboard with SLA status.', 1) RETURNING id;
INSERT INTO gn_faqs (tenant_id, question, answer, category, helpful_yes, helpful_no) VALUES (1, 'What is Growth Nations1', 'Growth Nations is India''s intelligent lending operating system — CRM, LOS, LMS, credit, BRE, underwriting, payments, collections, compliance and AI in one platform.', 'General', 13, 5) RETURNING id;
INSERT INTO gn_faqs (tenant_id, question, answer, category, helpful_yes, helpful_no) VALUES (1, 'Is the demo data real1', 'No. All customer, lead, application, loan and payment data is synthetic demo data generated for demonstration purposes only. Never use real personal or financial information.', 'General', 16, 1) RETURNING id;
INSERT INTO gn_faqs (tenant_id, question, answer, category, helpful_yes, helpful_no) VALUES (1, 'How do I capture a lead1', 'Create a lead manually in CRM → Leads, or via bulk import, or through campaigns — Meta, Google, WhatsApp and walk-in sources are supported.', 'Leads', 15, 7) RETURNING id;
INSERT INTO gn_faqs (tenant_id, question, answer, category, helpful_yes, helpful_no) VALUES (1, 'How do I submit an application to a lender1', 'Complete KYC, documents and credit checks, run the lender match, select the best offer and click Submit. The application is then tracked through underwriting, approval and sanction.', 'Applications', 33, 9) RETURNING id;
INSERT INTO gn_faqs (tenant_id, question, answer, category, helpful_yes, helpful_no) VALUES (1, 'When is commission earned1', 'Commission is earned when a loan is fully disbursed and the lender confirms disbursal. It becomes receivable at month-end and is paid out per your payout schedule.', 'Disbursement', 38, 9) RETURNING id;
INSERT INTO gn_faqs (tenant_id, question, answer, category, helpful_yes, helpful_no) VALUES (1, 'How does payment reconciliation work1', 'Bank/gateway transactions are imported, normalized, matched to loans by reference/amount/customer, and auto-reconciled. Exceptions land in a human-review queue with full audit.', 'Payments', 26, 6) RETURNING id;
INSERT INTO gn_faqs (tenant_id, question, answer, category, helpful_yes, helpful_no) VALUES (1, 'What is a Compliance Blocker1', 'When required KFS/APR information is missing before acceptance, the platform blocks the action and shows a Compliance Blocker so no hidden charges are ever passed to a customer.', 'Compliance', 50, 3) RETURNING id;
INSERT INTO gn_faqs (tenant_id, question, answer, category, helpful_yes, helpful_no) VALUES (1, 'Who can see customer data1', 'Access is controlled by role-based permissions. Every sensitive operation is audit-logged with who, what, when, IP and before/after values.', 'Security', 28, 4) RETURNING id;
INSERT INTO gn_faqs (tenant_id, question, answer, category, helpful_yes, helpful_no) VALUES (1, 'How do I raise a complaint1', 'Use Help & FAQ → New Ticket. You can track the ticket status and resolution from the same page.', 'Support', 48, 9) RETURNING id;
INSERT INTO gn_faqs (tenant_id, question, answer, category, helpful_yes, helpful_no) VALUES (1, 'What can NEXUS AI do1', 'NEXUS AI can search, analyze, summarize, compare, recommend and draft. It never autonomously approves, rejects, disburses or modifies financial records — human confirmation is always required.', 'AI', 55, 4) RETURNING id;
INSERT INTO gn_support_tickets (tenant_id, subject, message, priority, category, status, created_by, assigned_to, created_at) VALUES (1, 'Payout not reflecting in wallet', 'My July payout shows as processed but the amount is not in my wallet balance yet.', 'high', 'Payout', 'in_progress', 1, 4, (CURRENT_TIMESTAMP + CAST('-0 days' AS INTERVAL))) RETURNING id;
INSERT INTO gn_support_tickets (tenant_id, subject, message, priority, category, status, created_by, assigned_to, created_at) VALUES (1, 'Lender file rejected — need reason', 'SBI rejected my file but the reason is not visible on the application timeline.', 'urgent', 'Application', 'open', 1, 4, (CURRENT_TIMESTAMP + CAST('-3 days' AS INTERVAL))) RETURNING id;
INSERT INTO gn_support_tickets (tenant_id, subject, message, priority, category, status, created_by, assigned_to, created_at) VALUES (1, 'Unable to upload PAN card', 'The document upload keeps failing for the PAN card on this application.', 'medium', 'Documents', 'open', 1, 7, (CURRENT_TIMESTAMP + CAST('-2 days' AS INTERVAL))) RETURNING id;
INSERT INTO gn_support_tickets (tenant_id, subject, message, priority, category, status, created_by, assigned_to, created_at) VALUES (1, 'KFS amount mismatch', 'The KFS shows a processing fee higher than the scheme table.', 'high', 'Compliance', 'in_progress', 1, 1, (CURRENT_TIMESTAMP + CAST('-6 days' AS INTERVAL))) RETURNING id;
INSERT INTO gn_support_tickets (tenant_id, subject, message, priority, category, status, created_by, assigned_to, created_at) VALUES (1, 'DSA code not mapping to my partner', 'My applications are not attributing commission to my DSA code.', 'medium', 'Commission', 'open', 1, 1, (CURRENT_TIMESTAMP + CAST('-3 days' AS INTERVAL))) RETURNING id;
INSERT INTO gn_support_tickets (tenant_id, subject, message, priority, category, status, created_by, assigned_to, created_at) VALUES (1, 'Login issue on mobile', 'I cannot log in on my phone after the last update.', 'low', 'Login', 'resolved', 1, 1, (CURRENT_TIMESTAMP + CAST('-2 days' AS INTERVAL))) RETURNING id;
INSERT INTO gn_changelog (tenant_id, version, title, content, category, released_at) VALUES (1, '2.4.0', 'Command Center + Bulk Loan Application Processing', 'Added the GN Command Center (applicant funnel, lender matching, disbursement tracking), the bulk application engine with 500-applicant demo batches, and the API Center with mock provider endpoints.', 'feature', (CURRENT_TIMESTAMP + CAST('-0 days' AS INTERVAL))) RETURNING id;
INSERT INTO gn_changelog (tenant_id, version, title, content, category, released_at) VALUES (1, '2.3.0', 'Utility Dashboard', 'Added the Utility hub — pending approvals, bulk lead assign, document and import shortcuts.', 'feature', (CURRENT_TIMESTAMP + CAST('-4 days' AS INTERVAL))) RETURNING id;
INSERT INTO gn_changelog (tenant_id, version, title, content, category, released_at) VALUES (1, '2.2.1', 'Scheme form extended', 'Scheme forms now support banker identity, property area, TAT, rate notes, BT rules, enquiries and city tiers.', 'improvement', (CURRENT_TIMESTAMP + CAST('-7 days' AS INTERVAL))) RETURNING id;
INSERT INTO gn_changelog (tenant_id, version, title, content, category, released_at) VALUES (1, '2.2.0', 'Recycle Bin', 'Deleted records now move to a Recycle Bin with one-click restore — nothing is permanently lost by accident.', 'feature', (CURRENT_TIMESTAMP + CAST('-9 days' AS INTERVAL))) RETURNING id;
INSERT INTO gn_changelog (tenant_id, version, title, content, category, released_at) VALUES (1, '2.1.0', 'Inbox, Drips & Templates', 'Added the unified inbox with WhatsApp/SMS/email threads, drip campaigns and the template library.', 'feature', (CURRENT_TIMESTAMP + CAST('-11 days' AS INTERVAL))) RETURNING id;
INSERT INTO gn_changelog (tenant_id, version, title, content, category, released_at) VALUES (1, '2.0.5', 'Security hardening', 'Tenant isolation verified across all GN modules; sensitive operations audit-logged with before/after.', 'security', (CURRENT_TIMESTAMP + CAST('-14 days' AS INTERVAL))) RETURNING id;
INSERT INTO gn_changelog (tenant_id, version, title, content, category, released_at) VALUES (1, '2.0.0', 'Payment Reconciliation Center', 'Bank transaction import, auto-match, exception queue and reversals with immutable financial history.', 'feature', (CURRENT_TIMESTAMP + CAST('-20 days' AS INTERVAL))) RETURNING id;
INSERT INTO gn_changelog (tenant_id, version, title, content, category, released_at) VALUES (1, '1.9.0', 'KFS / APR Engine', 'Key Fact Statement generation with APR calculation and compliance blockers on missing disclosures.', 'feature', (CURRENT_TIMESTAMP + CAST('-28 days' AS INTERVAL))) RETURNING id;
